 add('h4',t('Mediciones en este paso','Measurements at this step'),panel);add('p',t('A = recomendada · B = tu secuencia. Dos instantes permiten ver también fallos intermitentes.','A = recommended · B = your sequence. Two sample times also reveal intermittent faults.'),panel);
 for(const time of [.5,1.25]){const table=add('table','',panel);table.className='guided-exam-scores';add('caption','t = '+time,table);const head=add('tr','',add('thead','',table));for(const label of [t('Prueba','Test'),'A','B'])add('th',label,head).scope='col';const body=add('tbody','',table),a=snapshot({...repairState(q.recommended),time}),b=snapshot({...repairState(q.user),time});for(const id of required[c.repair.kind]){const tr=add('tr','',body),av=reading(a,id),bv=reading(b,id);if(av!==bv)tr.className='sequence-difference';add('td',testName(id)+(av!==bv?t(' · Diferencia',' · Difference'):''),tr);add('td',av,tr);add('td',bv,tr);}}
 add('p',t('Antes de reparar, mide. Tras cada corrección, repite las pruebas y comprueba si queda otra causa. Los pasos omitidos no ahorran un tiempo físico calculado; solo eliminan intervenciones innecesarias del modelo.','Measure before repairing. After each correction, repeat the tests and check for another cause. Removed steps do not represent calculated physical time savings; they remove unnecessary interventions in this model.'),panel);
